/** FIPS -> [lat, lon]; parses the blob once per Worker isolate. */
export function countyCentroid(fips) {
  if (!_index) {
    _index = new Map();
    for (const row of COUNTY_CENTROID_BLOB.split(";")) {
      const a = row.indexOf(",");
      const b = row.indexOf(",", a + 1);
      if (a < 0 || b < 0) continue;
      _index.set(row.slice(0, a),
                 [+row.slice(a + 1, b), +row.slice(b + 1)]);
    }
  }
  return _index.get(String(fips).padStart(5, "0")) || null;
}
